SELECT p.id AS position_id, e.id, e.wallet_position_id, e.event_type, e.old_value_usdt, e.new_value_usdt, e.market_price_usdt, e.occurred_at, LEFT(e.reason,800) AS reason FROM paper_position p JOIN position_management_event e ON e.symbol=p.symbol AND e.occurred_at BETWEEN p.opened_at - INTERVAL 10 SECOND AND p.closed_at + INTERVAL 10 SECOND WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, e.occurred_at LIMIT 200;
SELECT a.paper_position_id, a.wallet_position_id, a.close_trigger, a.source_signal_id, a.source_signal_decision, a.source_signal_original_decision, a.exit_price_usdt, a.stop_loss_usdt, a.take_profit_usdt, a.audited_at, LEFT(a.close_explanation,800) AS expl FROM production_exit_audit a WHERE a.paper_position_id IN (182,172,162,158,143,137) ORDER BY a.paper_position_id